') == 'table':\n        content = el.get('content', '')\n        # Find all elements that might have TIPS price data\n        if 'TIPS' in content and ('price' in content.lower() or 'yield' in content.lower() or '01/15' in content):\n            print(f\"=== Element {i} ===\")\n            # Extract the table rows\n            print(content[:4000])\n            print(\"\\n\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
